try {
  return this.apply({
    assistantId: execution.assistantId,
    commandId: execution.commandId,
    mutation,
    execution: { ...execution, requestId: '', origin: { kind: 'user', jobId: execution.jobId } }
  })
} catch (error) {
  const prior = this.command(execution.commandId)
  if (prior?.receipt_json && prior.state === 'SUCCEEDED') return this.safeReceipt(JSON.parse(prior.receipt_json))
  this.store.database.prepare("UPDATE memory_commands SET state='NOT_APPLIED' WHERE id=? AND state='PREPARED'").run(execution.commandId)
  throw error
}
